FROM penguins |> WHERE body_mass_g IS NOT NULL |> AGGREGATE symbol(x => bill_length_mm, y => bill_depth_mm, color => species) AS bills GROUP BY island |> AS charts |> LEFT OUTER JOIN (FROM penguins |> WHERE body_mass_g IS NOT NULL |> AGGREGATE count(*) AS n GROUP BY island, species |> AGGREGATE bar(x => species, y => scaled(n, title => 'count(*)')) AS counts GROUP BY island) AS charts_2 ON charts.island IS NOT DISTINCT FROM charts_2.island |> SELECT charts.island, charts.bills, charts_2.counts |> ORDER BY island
